71	                marginTop: theme.spacing.sm,
72	                marginBottom: theme.spacing.sm,
73	                borderBottom: `1px solid ${theme.colors.actionDefaultBorderDefault}`,
74	              }}
75	            />
76	          ) : (
77	            <li css={{ paddingLeft: theme.spacing.lg, marginTop: theme.spacing.sm, marginBottom: theme.spacing.sm }}>
78	              <Typography.Text size="sm" color="secondary">
79	                {getExperimentPageSideNavSectionLabel(sectionKey as ExperimentPageSideNavSectionKey, items)}
80	              </Typography.Text>
81	            </li>
82	          )}
83	          {items.map((item) => {
84	            const isActive = () => {
85	              if (item.tabName === ExperimentPageTabName.ChatSessions) {
86	                return (
87	                  activeTabByRoute === ExperimentPageTabName.ChatSessions ||
88	                  activeTabByRoute === ExperimentPageTabName.SingleChatSession
89	                );
90	              }
91	              return activeTabByRoute === item.tabName;
92	            };
93	            const preserveQueryParams =
94	              activeTabByRoute && isTracesRelatedTab(activeTabByRoute) && isTracesRelatedTab(item.tabName);
95	            return (
96	              <MlflowSidebarLink
97	                css={{ paddingLeft: collapsed ? undefined : theme.spacing.lg }}
98	                key={item.componentId}
99	                to={{
100	                  pathname: ExperimentTrackingRoutes.getExperimentPageTabRoute(experimentId ?? '', item.tabName),
101	                  search: preserveQueryParams ? search : undefined,
102	                }}
103	                componentId={item.componentId}
104	                isActive={isActive}
105	                collapsed={collapsed}
106	                icon={item.icon}
107	              >
108	                {item.label}
109	              </MlflowSidebarLink>
110	            );
111	          })}
112	        </Fragment>
113	      ))}
114	      <div
115	        css={{
116	          borderBottom: `1px solid ${theme.colors.actionDefaultBorderDefault}`,
117	          width: '100%',
118	          paddingTop: theme.spacing.sm,
119	          marginBottom: theme.spacing.sm,
120	        }}
121	      />
122	    </>
123	  );
